function fit(value, limit) {
  const text = String(value ?? '').trim();
  const chars = Array.from(text);
  if (chars.length <= limit) return text;
  const brand = 'UsefulVerse';
  if (text.includes(brand)) {
    const suffix = ` | ${brand}`;
    const budget = limit - Array.from(suffix).length;
    let body = Array.from(text.replace(brand, '').replace(/[ |–—-]+$/u, '').trim()).slice(0, budget).join('');
    const boundary = body.lastIndexOf(' ');
    if (boundary >= Math.floor(budget * 0.62)) body = body.slice(0, boundary);
    return `${body.replace(/[\\s|,:;–—-]+$/u, '').trim()}${suffix}`;
  }
  let shortened = chars.slice(0, limit - 1).join('');
  const boundary = shortened.lastIndexOf(' ');
  if (boundary >= Math.floor(limit * 0.62)) shortened = shortened.slice(0, boundary);
  return shortened.replace(/[\\s|,:;–—-]+$/u, '').trim() + '…';
}
function localize(value, translated) {
  if (typeof value === 'string') {
    const index = stringIndex.get(value);
    return index === undefined ? value : translated[index].replaceAll('ZXBRANDTOKENZX', 'UsefulVerse');
  }
  if (Array.isArray(value)) return value.map((item) => localize(item, translated));
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, localize(item, translated)]));
  return value;
}
